/**
 * How to parse. `Default` is what the SVG spec calls for, with system fonts.
 */
public struct ParseOptions {
    /**
     * Load the system's fonts so `<text>` in a face the document doesn't embed
     * still lays out. Loading is a directory walk done once per process and
     * shared by every document after; off, text in an unknown family falls
     * back to nothing and is dropped, which is what a sandboxed host with no
     * font access wants.
     */
    public var loadSystemFonts: Bool
    /**
     * The family for text that names none. usvg's default is Times New Roman.
     */
    public var fontFamily: String
    /**
     * The size for text that sets none, in user units.
     */
    public var fontSize: Float
    /**
     * Dots per inch, for `in`/`cm`/`mm` lengths. 96 is CSS's.
     */
    public var dpi: Float
    /**
     * Directory that relative `href`s (in `<image>`) resolve against; `None`
     * leaves them unresolved.
     */
    public var resourcesDir: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Load the system's fonts so `<text>` in a face the document doesn't embed
         * still lays out. Loading is a directory walk done once per process and
         * shared by every document after; off, text in an unknown family falls
         * back to nothing and is dropped, which is what a sandboxed host with no
         * font access wants.
         */loadSystemFonts: Bool = true, 
        /**
         * The family for text that names none. usvg's default is Times New Roman.
         */fontFamily: String = "Times New Roman", 
        /**
         * The size for text that sets none, in user units.
         */fontSize: Float = Float(12.0), 
        /**
         * Dots per inch, for `in`/`cm`/`mm` lengths. 96 is CSS's.
         */dpi: Float = Float(96.0), 
        /**
         * Directory that relative `href`s (in `<image>`) resolve against; `None`
         * leaves them unresolved.
         */resourcesDir: String? = nil) {
        self.loadSystemFonts = loadSystemFonts
        self.fontFamily = fontFamily
        self.fontSize = fontSize
        self.dpi = dpi
        self.resourcesDir = resourcesDir
    }
}



extension ParseOptions: Equatable, Hashable {
    public static func ==(lhs: ParseOptions, rhs: ParseOptions) -> Bool {
        if lhs.loadSystemFonts != rhs.loadSystemFonts {
            return false
        }
        if lhs.fontFamily != rhs.fontFamily {
            return false
        }
        if lhs.fontSize != rhs.fontSize {
            return false
        }
        if lhs.dpi != rhs.dpi {
            return false
        }
        if lhs.resourcesDir != rhs.resourcesDir {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(loadSystemFonts)
        hasher.combine(fontFamily)
        hasher.combine(fontSize)
        hasher.combine(dpi)
        hasher.combine(resourcesDir)
    }
}


