/**
 * A radial gradient: from the focal point `(fx, fy)` at radius 0 to the
 * circle centred `(cx, cy)` at radius `r`.
 */
public struct RadialGradient {
    public var cx: Float
    public var cy: Float
    public var r: Float
    public var fx: Float
    public var fy: Float
    public var transform: Transform
    /**
     * At least two, offsets ascending in `0.0..=1.0`.
     */
    public var stops: [Stop]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(cx: Float, cy: Float, r: Float, fx: Float, fy: Float, transform: Transform, 
        /**
         * At least two, offsets ascending in `0.0..=1.0`.
         */stops: [Stop]) {
        self.cx = cx
        self.cy = cy
        self.r = r
        self.fx = fx
        self.fy = fy
        self.transform = transform
        self.stops = stops
    }
}



extension RadialGradient: Equatable, Hashable {
    public static func ==(lhs: RadialGradient, rhs: RadialGradient) -> Bool {
        if lhs.cx != rhs.cx {
            return false
        }
        if lhs.cy != rhs.cy {
            return false
        }
        if lhs.r != rhs.r {
            return false
        }
        if lhs.fx != rhs.fx {
            return false
        }
        if lhs.fy != rhs.fy {
            return false
        }
        if lhs.transform != rhs.transform {
            return false
        }
        if lhs.stops != rhs.stops {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(cx)
        hasher.combine(cy)
        hasher.combine(r)
        hasher.combine(fx)
        hasher.combine(fy)
        hasher.combine(transform)
        hasher.combine(stops)
    }
}


