/**
 * A 2D affine transform: `x' = sx·x + kx·y + tx`, `y' = ky·x + sy·y + ty`.
 * `CGAffineTransform(a: sx, b: ky, c: kx, d: sy, tx, ty)` is the same matrix.
 */
public struct Transform {
    public var sx: Float
    public var kx: Float
    public var ky: Float
    public var sy: Float
    public var tx: Float
    public var ty: Float

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(sx: Float, kx: Float, ky: Float, sy: Float, tx: Float, ty: Float) {
        self.sx = sx
        self.kx = kx
        self.ky = ky
        self.sy = sy
        self.tx = tx
        self.ty = ty
    }
}



extension Transform: Equatable, Hashable {
    public static func ==(lhs: Transform, rhs: Transform) -> Bool {
        if lhs.sx != rhs.sx {
            return false
        }
        if lhs.kx != rhs.kx {
            return false
        }
        if lhs.ky != rhs.ky {
            return false
        }
        if lhs.sy != rhs.sy {
            return false
        }
        if lhs.tx != rhs.tx {
            return false
        }
        if lhs.ty != rhs.ty {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(sx)
        hasher.combine(kx)
        hasher.combine(ky)
        hasher.combine(sy)
        hasher.combine(tx)
        hasher.combine(ty)
    }
}


