// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * `mix-blend-mode`, the sixteen CSS compositing modes.
 */

public enum BlendMode {
    
    case normal
    case multiply
    case screen
    case overlay
    case darken
    case lighten
    case colorDodge
    case colorBurn
    case hardLight
    case softLight
    case difference
    case exclusion
    case hue
    case saturation
    case color
    case luminosity
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlendMode: FfiConverterRustBuffer {
    typealias SwiftType = BlendMode

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlendMode {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .normal
        
        case 2: return .multiply
        
        case 3: return .screen
        
        case 4: return .overlay
        
        case 5: return .darken
        
        case 6: return .lighten
        
        case 7: return .colorDodge
        
        case 8: return .colorBurn
        
        case 9: return .hardLight
        
        case 10: return .softLight
        
        case 11: return .difference
        
        case 12: return .exclusion
        
        case 13: return .hue
        
        case 14: return .saturation
        
        case 15: return .color
        
        case 16: return .luminosity
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlendMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case .normal:
            writeInt(&buf, Int32(1))
        
        
        case .multiply:
            writeInt(&buf, Int32(2))
        
        
        case .screen:
            writeInt(&buf, Int32(3))
        
        
        case .overlay:
            writeInt(&buf, Int32(4))
        
        
        case .darken:
            writeInt(&buf, Int32(5))
        
        
        case .lighten:
            writeInt(&buf, Int32(6))
        
        
        case .colorDodge:
            writeInt(&buf, Int32(7))
        
        
        case .colorBurn:
            writeInt(&buf, Int32(8))
        
        
        case .hardLight:
            writeInt(&buf, Int32(9))
        
        
        case .softLight:
            writeInt(&buf, Int32(10))
        
        
        case .difference:
            writeInt(&buf, Int32(11))
        
        
        case .exclusion:
            writeInt(&buf, Int32(12))
        
        
        case .hue:
            writeInt(&buf, Int32(13))
        
        
        case .saturation:
            writeInt(&buf, Int32(14))
        
        
        case .color:
            writeInt(&buf, Int32(15))
        
        
        case .luminosity:
            writeInt(&buf, Int32(16))
        
        }
    }
}


