/**
 * How a path's interior is decided.
 */

public enum FillRule {
    
    case nonZero
    case evenOdd
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFillRule: FfiConverterRustBuffer {
    typealias SwiftType = FillRule

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FillRule {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .nonZero
        
        case 2: return .evenOdd
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FillRule, into buf: inout [UInt8]) {
        switch value {
        
        
        case .nonZero:
            writeInt(&buf, Int32(1))
        
        
        case .evenOdd:
            writeInt(&buf, Int32(2))
        
        }
    }
